"""Pinned private package handling for Controller Overlay Pro #707."""

from __future__ import annotations

import hashlib
import io
import json
import os
import shutil
import stat
import tempfile
import zipfile
from collections import Counter
from dataclasses import dataclass
from pathlib import Path

from . import community_plugins


class ControllerOverlayError(RuntimeError):
    """The exact reviewed Controller Overlay Pro package was not available."""


PLUGIN_ID = "707"
PUBLIC_VERSION = "1.0.7"
EMBEDDED_CVAR_VERSION = "1.0.5"
API_VERSION = 3
OFFICIAL_DOWNLOAD_URL = (
    "https://cdn.bakkesplugins.com/uploads/"
    "feb57eac272f4f0a8f95865f86d182be-Bakkesplugin_707-public-20260411-204747.zip"
)
ARCHIVE_SHA256 = "9377316bb9649c9ee131d265e8fd08b14a792ad7c03f6adb15e3aee72bad72d7"
ARCHIVE_BYTES = 850_492
ENTRY_COUNT = 62
UNCOMPRESSED_BYTES = 1_158_670
DLL_MEMBER = "plugins/ControllerOverlayPro.dll"
DLL_SHA256 = "a56759e12fc302180c782cff44f332c07a7a6c3106b0e345b90c238e1fc5ae4d"
DLL_BYTES = 473_088
CVAR_NAMES = ("xco_enabled", "xco_x", "xco_y", "xco_scale", "xco_skin")
_FAMILY_COUNTS = {
    "data/ControllerOverlayPro/EasterEgg": 6,
    "data/ControllerOverlayPro/skins/Default": 10,
    "data/ControllerOverlayPro/skins/ps4": 15,
    "data/ControllerOverlayPro/skins/ps5": 15,
    "data/ControllerOverlayPro/skins/xbox": 15,
}
_PACKAGE_FOLDER = "controller-overlay-707-package"
_MANIFEST = "controller-overlay-707.json"


@dataclass(frozen=True, slots=True)
class InstalledControllerOverlay:
    dll_path: Path
    installed: bool
    verified: bool
    package_version: str | None
    embedded_cvar_version: str | None
    dll_sha256: str | None
    cvars_found: tuple[str, ...]
    assets_complete: bool

    @property
    def supported(self) -> bool:
        return self.verified and self.assets_complete and self.cvars_found == CVAR_NAMES


@dataclass(frozen=True, slots=True)
class StagedControllerOverlay:
    archive_path: Path
    package_path: Path
    archive_sha256: str
    package_version: str
    can_activate: bool = True


def cached_package(cache_directory: Path) -> StagedControllerOverlay | None:
    """Return the exact cached release, if an explicit download already saved it."""
    try:
        receipts = community_plugins.cached_plugins(Path(cache_directory))
    except community_plugins.CommunityPluginError as error:
        raise ControllerOverlayError(str(error)) from None
    receipt = next((item for item in receipts if item.get("id") == PLUGIN_ID
                    and item.get("artifact_sha256") == ARCHIVE_SHA256), None)
    return stage_cached_package(receipt, cache_directory) if receipt else None


def activation_files(staged: StagedControllerOverlay) -> dict[str, Path]:
    """Reverify a staged package and expose only its pinned DLL and PNG members."""
    if not isinstance(staged, StagedControllerOverlay) or staged.archive_sha256 != ARCHIVE_SHA256:
        raise ControllerOverlayError("The staged Controller Overlay Pro package is not the reviewed release.")
    try:
        expected = _validate_archive(staged.archive_path.read_bytes())
    except OSError:
        raise ControllerOverlayError("The staged Controller Overlay Pro package is not the reviewed release.") from None
    _validate_staged(staged.package_path, _expected_manifest(expected))
    return {name: staged.package_path.joinpath(*name.split("/")) for name in expected}


def inspect_installed(bakkes_root: Path) -> InstalledControllerOverlay:
    """Describe an existing installation without executing or changing it."""
    root = Path(bakkes_root)
    dll = root / DLL_MEMBER
    if not _regular_file(dll):
        return InstalledControllerOverlay(dll, False, False, None, None, None, (), False)
    try:
        if dll.stat().st_size > 16 * 1024 * 1024:
            raise OSError
        payload = dll.read_bytes()
    except OSError:
        return InstalledControllerOverlay(dll, True, False, None, None, None, (), False)
    digest = hashlib.sha256(payload).hexdigest()
    found = tuple(name for name in CVAR_NAMES if name.encode("ascii") in payload)
    verified = len(payload) == DLL_BYTES and digest == DLL_SHA256
    return InstalledControllerOverlay(
        dll_path=dll,
        installed=True,
        verified=verified,
        package_version=PUBLIC_VERSION if verified else None,
        embedded_cvar_version=EMBEDDED_CVAR_VERSION if verified else None,
        dll_sha256=digest,
        cvars_found=found,
        assets_complete=_installed_assets_complete(root),
    )


def download_and_stage(cache_directory: Path, *, opener=None) -> StagedControllerOverlay:
    """Download the current official release, accepting only the reviewed bytes."""
    try:
        record = community_plugins.lookup_plugin(PLUGIN_ID, opener=opener)
    except community_plugins.CommunityPluginError as error:
        raise ControllerOverlayError(str(error)) from None
    if (record.get("version") != API_VERSION or record.get("download_url") != OFFICIAL_DOWNLOAD_URL
            or record.get("site_verified") is not True):
        raise ControllerOverlayError("Controller Overlay Pro's official release changed; review it before staging.")
    try:
        receipt = community_plugins.download_plugin(record, Path(cache_directory), opener=opener)
    except community_plugins.CommunityPluginError as error:
        raise ControllerOverlayError(str(error)) from None
    return stage_cached_package(receipt, Path(cache_directory))


def stage_cached_package(receipt: dict, cache_directory: Path) -> StagedControllerOverlay:
    """Validate and privately extract the exact cached #707 archive."""
    expected_archive = f"objects/{ARCHIVE_SHA256}/archive.zip"
    if (not isinstance(receipt, dict) or receipt.get("id") != PLUGIN_ID
            or receipt.get("version") != API_VERSION
            or receipt.get("download_url") != OFFICIAL_DOWNLOAD_URL
            or receipt.get("artifact_sha256") != ARCHIVE_SHA256
            or receipt.get("archive") != expected_archive
            or receipt.get("can_activate") is not False):
        raise ControllerOverlayError("The cached Controller Overlay Pro receipt is not the reviewed release.")
    try:
        root = community_plugins._cache_root(Path(cache_directory), create=False)
    except community_plugins.CommunityPluginError as error:
        raise ControllerOverlayError(str(error)) from None
    if root is None:
        raise ControllerOverlayError("The private community cache is unavailable.")
    archive_path = root / "objects" / ARCHIVE_SHA256 / "archive.zip"
    if not _regular_file(archive_path):
        raise ControllerOverlayError("The reviewed Controller Overlay Pro archive is missing from the private cache.")
    try:
        archive = archive_path.read_bytes()
        files = _validate_archive(archive)
    except OSError:
        raise ControllerOverlayError("The reviewed Controller Overlay Pro archive could not be read.") from None
    object_directory = archive_path.parent
    final = object_directory / _PACKAGE_FOLDER
    manifest = _expected_manifest(files)
    if final.exists() or final.is_symlink():
        _validate_staged(final, manifest)
        return StagedControllerOverlay(archive_path, final, ARCHIVE_SHA256, PUBLIC_VERSION)

    staging = Path(tempfile.mkdtemp(prefix=".controller-overlay-707-", dir=object_directory))
    try:
        with zipfile.ZipFile(archive_path) as bundle:
            for info in bundle.infolist():
                target = staging.joinpath(*info.filename.split("/"))
                target.parent.mkdir(parents=True, exist_ok=True)
                with bundle.open(info) as source, target.open("xb") as destination:
                    shutil.copyfileobj(source, destination, length=64 * 1024)
        (staging / _MANIFEST).write_text(
            json.dumps(manifest, ensure_ascii=True, allow_nan=False, indent=2), encoding="ascii"
        )
        _validate_staged(staging, manifest)
        try:
            os.rename(staging, final)
        except FileExistsError:
            _validate_staged(final, manifest)
    except ControllerOverlayError:
        raise
    except (OSError, zipfile.BadZipFile, RuntimeError):
        raise ControllerOverlayError("Controller Overlay Pro could not be staged in the private cache.") from None
    finally:
        if staging.exists():
            shutil.rmtree(staging)
    return StagedControllerOverlay(archive_path, final, ARCHIVE_SHA256, PUBLIC_VERSION)


def _validate_archive(archive: bytes) -> dict[str, tuple[int, str]]:
    if len(archive) != ARCHIVE_BYTES or hashlib.sha256(archive).hexdigest() != ARCHIVE_SHA256:
        raise ControllerOverlayError("Controller Overlay Pro archive bytes do not match the reviewed release.")
    try:
        package = community_plugins._inspect_zip(archive)
    except community_plugins.CommunityPluginError as error:
        raise ControllerOverlayError(str(error)) from None
    if (package["entry_count"] != ENTRY_COUNT or package["file_count"] != ENTRY_COUNT
            or package["directory_count"] != 0
            or package["uncompressed_bytes"] != UNCOMPRESSED_BYTES):
        raise ControllerOverlayError("Controller Overlay Pro archive inventory does not match the reviewed release.")
    names = [item["name"] for item in package["entries"]]
    families = Counter(_family(name) for name in names if name != DLL_MEMBER)
    if set(names) != {DLL_MEMBER, *(name for name in names if name.endswith(".png"))} or families != _FAMILY_COUNTS:
        raise ControllerOverlayError("Controller Overlay Pro archive paths do not match the reviewed release.")
    files: dict[str, tuple[int, str]] = {}
    with zipfile.ZipFile(io.BytesIO(archive)) as bundle:
        for info in bundle.infolist():
            payload = bundle.read(info)
            files[info.filename] = (len(payload), hashlib.sha256(payload).hexdigest())
    dll_size, dll_hash = files.get(DLL_MEMBER, (0, ""))
    if dll_size != DLL_BYTES or dll_hash != DLL_SHA256:
        raise ControllerOverlayError("Controller Overlay Pro DLL does not match the reviewed release.")
    return files


def _family(name: str) -> str:
    if name.startswith("data/ControllerOverlayPro/EasterEgg/"):
        return "data/ControllerOverlayPro/EasterEgg"
    pieces = name.split("/")
    return "/".join(pieces[:4]) if len(pieces) == 5 else ""


def _expected_manifest(files: dict[str, tuple[int, str]]) -> dict:
    return {
        "schema": 1,
        "plugin_id": PLUGIN_ID,
        "package_version": PUBLIC_VERSION,
        "archive_sha256": ARCHIVE_SHA256,
        "can_activate": False,
        "files": [
            {"name": name, "bytes": size, "sha256": digest}
            for name, (size, digest) in sorted(files.items())
        ],
    }


def _validate_staged(directory: Path, manifest: dict) -> None:
    if directory.is_symlink() or not directory.is_dir():
        raise ControllerOverlayError("A foreign file occupies the Controller Overlay Pro staging path.")
    expected = {_MANIFEST, *(item["name"] for item in manifest["files"])}
    for item in manifest["files"]:
        parts = item["name"].split("/")
        expected.update("/".join(parts[:index]) for index in range(1, len(parts)))
    try:
        entries = list(directory.rglob("*"))
        actual = {path.relative_to(directory).as_posix() for path in entries}
        if (actual != expected
                or any(path.is_symlink() or community_plugins._is_junction(path) for path in entries)):
            raise ControllerOverlayError("The existing Controller Overlay Pro staging folder was left unchanged.")
        loaded = json.loads((directory / _MANIFEST).read_text(encoding="ascii"))
        if loaded != manifest:
            raise ControllerOverlayError("The existing Controller Overlay Pro staging folder was left unchanged.")
        for item in manifest["files"]:
            path = directory.joinpath(*item["name"].split("/"))
            if (not _regular_file(path) or path.stat().st_size != item["bytes"]
                    or hashlib.sha256(path.read_bytes()).hexdigest() != item["sha256"]):
                raise ControllerOverlayError("The existing Controller Overlay Pro staging folder was left unchanged.")
    except (OSError, UnicodeError, json.JSONDecodeError):
        raise ControllerOverlayError("The existing Controller Overlay Pro staging folder was left unchanged.") from None


def _installed_assets_complete(root: Path) -> bool:
    for family, count in _FAMILY_COUNTS.items():
        directory = root.joinpath(*family.split("/"))
        try:
            files = [path for path in directory.iterdir() if _regular_file(path) and path.suffix.casefold() == ".png"]
        except OSError:
            return False
        if len(files) < count:
            return False
    return True


def _regular_file(path: Path) -> bool:
    try:
        return not path.is_symlink() and stat.S_ISREG(path.stat(follow_symlinks=False).st_mode)
    except OSError:
        return False
